use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::observe_retirement_allocations as observe;


#[test]
fn scalar_denied_payload_keeps_private_binding_and_value_empty(){let mut birth=RetainedCloneSource::admission_owned(42u64,());let mut out=None;let mut cpu=100000u64;for _ in 0..128{if birth.terminal_is_empty(){break}let d=birth.next_demand().unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let mut actual=None;let turn=if birth.phase()=="ready"{birth.take_output(&mut out,g)}else{birth.advance(g,&mut actual)};cpu=cpu.checked_sub(turn.work).unwrap();turn.result.unwrap();}assert!(birth.terminal_is_empty());let mut source=out.unwrap();let mut cursor=u64::retained_clone_cursor();for g in[RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:8,maximum_depth:1,..Default::default()},RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_depth:1,..Default::default()},RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:7,maximum_depth:1,..Default::default()},RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:8,maximum_depth:0,..Default::default()}]{let before=cursor.source.is_some();let(t,h)=observe(||cursor.advance(source.borrow(),8,1,g));assert_eq!(h,(0,0));assert_eq!(t.work,0);assert_eq!(t.result.as_ref().map_or_else(|e|e.retained_progress(),|s|s.progress()),Default::default());assert_eq!(cursor.source.is_some(),before);assert!(cursor.value.is_none());}let t=cursor.begin_close_paid();cpu=cpu.checked_sub(t.work).unwrap();t.result.unwrap();assert!(cursor.terminal_is_empty());for n in 0..10000{if source.terminal_is_empty(){break}let d=source.next_close_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(t,h)=observe(||source.close_step(g));cpu=cpu.checked_sub(t.work).unwrap();let p=t.result.unwrap().progress();assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));assert!(n<9999)}assert!(source.terminal_is_empty());assert_eq!(observe(||drop((cursor,source))).1,(0,0));}

#[test]
fn scalar_lifecycle_state_matrix_preserves_private_cursor_phase(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../🧮️scalar/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in law["lifecycle"].as_array().unwrap(){let mut cursor=ScalarCursor::<u64>::default();cursor.value=row["output"].as_bool().unwrap().then_some(42);cursor.closing=row["closing"].as_bool().unwrap();cursor.spent=row["spent"].as_bool().unwrap();assert_eq!(cursor.output_ready(),row["ready"].as_bool().unwrap());if !cursor.output_ready(){let turn=cursor.take(Default::default());assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());}cursor.value=None;}
}
